?><!doctype html>
<html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Productos | Mi Store Arequipa</title>
<style>
*{box-sizing:border-box}body{margin:0;background:#f4f6f8;color:#20242b;font-family:Inter,system-ui,Arial,sans-serif}.top{background:#17191d;color:white;padding:17px max(20px,calc((100% - 1180px)/2));display:flex;justify-content:space-between;align-items:center;gap:15px}.top a{color:white;text-decoration:none}.wrap{max-width:1180px;margin:28px auto;padding:0 20px}.head{display:flex;align-items:center;justify-content:space-between;gap:16px;flex-wrap:wrap}.muted{color:#68717d}.btn{border:0;border-radius:9px;padding:10px 15px;font-weight:650;cursor:pointer;text-decoration:none;display:inline-flex;align-items:center;justify-content:center}.primary{background:#e53935;color:white}.secondary{background:#e9edf1;color:#252a31}.danger{background:#fff0ef;color:#bd2925}.panel{background:white;border-radius:15px;padding:20px;margin-top:20px;box-shadow:0 5px 22px #17202a0b}.toolbar{display:flex;gap:10px;flex-wrap:wrap;margin:15px 0}.toolbar input{flex:1;min-width:220px}.field,input,textarea,select{width:100%;padding:11px 12px;border:1px solid #dce1e6;border-radius:8px;font:inherit;background:white}.table-wrap{overflow:auto}table{width:100%;border-collapse:collapse;min-width:760px}th,td{text-align:left;padding:12px;border-bottom:1px solid #edf0f2;font-size:14px}th{color:#68717d;font-size:12px;text-transform:uppercase}td img{width:48px;height:48px;object-fit:contain;border-radius:8px;background:#f5f6f7}.actions{display:flex;gap:7px;flex-wrap:wrap}.status{font-size:12px;padding:4px 8px;border-radius:20px;background:#e8f7ed;color:#237443}.off{background:#f0f1f3;color:#68717d}.empty{text-align:center;padding:28px;color:#68717d}.modal{display:none;position:fixed;inset:0;background:#10131899;padding:20px;overflow:auto;z-index:5}.modal.open{display:grid;place-items:center}.dialog{width:min(680px,100%);background:white;border-radius:16px;padding:22px}.formgrid{display:grid;grid-template-columns:1fr 1fr;gap:13px}.formgrid .full{grid-column:1/-1}label{display:block;font-size:13px;font-weight:650;margin-bottom:6px}.check{display:flex;align-items:center;gap:9px}.check input{width:auto}.footer-actions{display:flex;justify-content:flex-end;gap:9px;margin-top:18px}.notice{padding:11px 14px;border-radius:9px;margin-top:14px;display:none}.notice.show{display:block}.notice.ok{background:#e8f7ed;color:#237443}.notice.err{background:#fff0ef;color:#bd2925}@media(max-width:600px){.formgrid{grid-template-columns:1fr}.formgrid .full{grid-column:auto}.top{align-items:flex-start;flex-direction:column}}
</style></head><body>
<header class="top"><strong>Mi Store Arequipa · Productos</strong><nav style="display:flex;gap:18px;flex-wrap:wrap"><a href="index.php">Panel principal</a><a href="../index.php">Ver tienda</a><a href="../backend/logout.php">Cerrar sesión</a></nav></header>
<main class="wrap"><div class="head"><div><h1 style="margin:0">Gestión de productos</h1><p class="muted">Crea productos, actualiza precios y controla el inventario.</p></div><button class="btn primary" id="nuevoProducto">+ Nuevo producto</button></div>
<div id="notice" class="notice"></div>
<section class="panel"><div class="toolbar"><input id="buscar" placeholder="Buscar por nombre o categoría..."><select id="filtroEstado" style="max-width:190px"><option value="todos">Todos los estados</option><option value="1">Activos</option><option value="0">Inactivos</option></select></div><div class="table-wrap"><table><thead><tr><th>Imagen</th><th>Producto</th><th>Categoría</th><th>Precio</th><th>Stock</th><th>Estado</th><th>Acciones</th></tr></thead><tbody id="productosBody"><tr><td colspan="7" class="empty">Cargando productos...</td></tr></tbody></table></div></section></main>
<div class="modal" id="modalProducto" role="dialog" aria-modal="true" aria-labelledby="modalTitulo"><div class="dialog"><h2 id="modalTitulo">Nuevo producto</h2><form id="formProducto" enctype="multipart/form-data"><input type="hidden" name="csrf_token" value="<?= htmlspecialchars($csrf, ENT_QUOTES) ?>"><input type="hidden" name="id"><input type="hidden" name="imagen_actual"><input type="hidden" name="action" value="crear"><div class="formgrid">
<div class="full"><label for="nombre">Nombre *</label><input id="nombre" name="nombre" maxlength="180" required></div>
<div><label for="categoria">Categoría *</label><input id="categoria" name="categoria" list="categorias" required><datalist id="categorias"><option>Celulares</option><option>Audio y Wearables</option><option>Hogar</option><option>Accesorios</option></datalist></div>
<div><label for="precio">Precio (S/) *</label><input id="precio" name="precio" type="number" min="0" step="0.01" required></div>
<div><label for="stock">Stock *</label><input id="stock" name="stock" type="number" min="0" step="1" required></div>
<div class="full"><label for="imagen_url">Enlace de imagen (URL)</label><input id="imagen_url" name="imagen_url" type="url" maxlength="2000" placeholder="https://sitio.com/imagen-producto.jpg"><small class="muted">Pega el enlace directo de la imagen. Si subes un archivo, el archivo tendrá prioridad.</small><div style="margin-top:8px"><img id="previewImagen" src="https://placehold.co/180x120?text=Vista+previa" alt="Vista previa" style="width:180px;height:120px;object-fit:contain;border:1px solid #e5e7eb;border-radius:8px;background:#fafafa"></div></div><div class="full"><label for="imagen">O subir imagen (JPG, PNG o WEBP, máx. 4 MB)</label><input id="imagen" name="imagen" type="file" accept="image/jpeg,image/png,image/webp"></div>
<div class="full"><label for="descripcion">Descripción</label><textarea id="descripcion" name="descripcion" rows="3" maxlength="5000"></textarea></div>
<label class="check full"><input type="checkbox" name="activo" checked> Producto visible en la tienda</label>
</div><div class="footer-actions"><button type="button" class="btn secondary" id="cancelar">Cancelar</button><button class="btn primary" type="submit" id="guardar">Guardar producto</button></div></form></div></div>
<script>
const API='../backend/admin_productos.php', csrf='<?= htmlspecialchars($csrf, ENT_QUOTES) ?>';
const body=document.getElementById('productosBody'), modal=document.getElementById('modalProducto'), form=document.getElementById('formProducto'), notice=document.getElementById('notice');let products=[];
function msg(text,ok=true){notice.textContent=text;notice.className='notice show '+(ok?'ok':'err');window.scrollTo({top:0,behavior:'smooth'});}
function esc(v=''){return String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function imagePath(path){if(!path)return '';path=String(path).trim();if(path.startsWith('//'))return location.protocol+path;if(/^https?:\/\//i.test(path))return path;return '../'+path.replace(/^\.\//,'').replace(/^\//,'');}
function render(){const q=document.getElementById('buscar').value.toLowerCase(),st=document.getElementById('filtroEstado').value;const list=products.filter(p=>(st==='todos'||String(p.activo)===st)&&(`${p.nombre} ${p.categoria}`.toLowerCase().includes(q)));if(!list.length){body.innerHTML='<tr><td colspan="7" class="empty">No hay productos que coincidan.</td></tr>';return;}body.innerHTML=list.map(p=>`<tr><td>${p.imagen?`<img src="${esc(imagePath(p.imagen))}" alt="" onerror="this.onerror=null;this.src='https://placehold.co/100x100?text=Sin+imagen'">`:'<span>—</span>'}</td><td><strong>${esc(p.nombre)}</strong><br><small class="muted">ID: ${p.id}</small></td><td>${esc(p.categoria)}</td><td>S/ ${Number(p.precio).toFixed(2)}</td><td>${p.stock}</td><td><span class="status ${p.activo?'':'off'}">${p.activo?'Activo':'Inactivo'}</span></td><td><div class="actions"><button class="btn secondary" data-edit="${p.id}">Editar</button><button class="btn ${p.activo?'danger':'secondary'}" data-toggle="${p.id}" data-active="${p.activo}">${p.activo?'Desactivar':'Activar'}</button></div></td></tr>`).join('');}
async function load(){body.innerHTML='<tr><td colspan="7" class="empty">Cargando...</td></tr>';try{const r=await fetch(API,{credentials:'same-origin'}),d=await r.json();if(!r.ok||!d.success)throw Error(d.message||'Error al cargar');products=d.products;render();}catch(e){body.innerHTML=`<tr><td colspan="7" class="empty">${esc(e.message)}</td></tr>`;}}
function openNew(){form.reset();form.elements.action.value='crear';form.elements.id.value='';form.elements.imagen_actual.value='';form.elements.imagen_url.value='';document.getElementById('previewImagen').src='https://placehold.co/180x120?text=Vista+previa';form.elements.activo.checked=true;document.getElementById('modalTitulo').textContent='Nuevo producto';modal.classList.add('open');}
function openEdit(id){const p=products.find(x=>Number(x.id)===Number(id));if(!p)return;form.reset();form.elements.action.value='actualizar';form.elements.id.value=p.id;form.elements.nombre.value=p.nombre;form.elements.categoria.value=p.categoria;form.elements.precio.value=p.precio;form.elements.stock.value=p.stock;form.elements.descripcion.value=p.descripcion||'';form.elements.imagen_actual.value=p.imagen||'';form.elements.imagen_url.value=/^https?:\/\//i.test(p.imagen||'')?p.imagen:'';document.getElementById('previewImagen').src=imagePath(p.imagen)||'https://placehold.co/180x120?text=Vista+previa';form.elements.activo.checked=Number(p.activo)===1;document.getElementById('modalTitulo').textContent='Editar producto #'+p.id;modal.classList.add('open');}
async function send(data){const r=await fetch(API,{method:'POST',body:data,credentials:'same-origin'});const d=await r.json();if(!r.ok||!d.success)throw Error(d.message||'No se pudo completar la operación');return d;}
document.getElementById('imagen_url').addEventListener('input',e=>{const v=e.target.value.trim();if(v)document.getElementById('previewImagen').src=v;});document.getElementById('imagen').addEventListener('change',e=>{const f=e.target.files?.[0];if(f)document.getElementById('previewImagen').src=URL.createObjectURL(f);});document.getElementById('nuevoProducto').addEventListener('click',openNew);document.getElementById('cancelar').addEventListener('click',()=>modal.classList.remove('open'));modal.addEventListener('click',e=>{if(e.target===modal)modal.classList.remove('open')});document.getElementById('buscar').addEventListener('input',render);document.getElementById('filtroEstado').addEventListener('change',render);
form.addEventListener('submit',async e=>{e.preventDefault();const b=document.getElementById('guardar');b.disabled=true;b.textContent='Guardando...';try{const d=await send(new FormData(form));modal.classList.remove('open');msg(d.message);await load();}catch(err){msg(err.message,false);}finally{b.disabled=false;b.textContent='Guardar producto';}});
body.addEventListener('click',async e=>{const edit=e.target.closest('[data-edit]'),toggle=e.target.closest('[data-toggle]');if(edit){openEdit(edit.dataset.edit);return;}if(toggle){const id=toggle.dataset.toggle,active=Number(toggle.dataset.active);if(active&&!confirm('¿Desactivar este producto? Dejará de mostrarse en la tienda, pero se conservará en los pedidos.'))return;const fd=new FormData();fd.append('csrf_token',csrf);fd.append('id',id);fd.append('action','cambiar_estado');fd.append('activo',active?0:1);try{const d=await send(fd);msg(d.message);await load();}catch(err){msg(err.message,false);}}});
load();
</script></body></html>
